/*
* Generate the shared inputs which every fixture runner reads.
*
* ## Notes
*
* -   Run with `node scripts/inputs.js` from the package directory. No fixture target discovers this script, as it is not under `test/fixtures/`.
* -   For each regime, the script writes `test/fixtures/inputs/<regime>.json`. Every fixture runner reads its inputs from these files, and echoes them in its own output, so a misread input shows up when the output is scored.
* -   Output is deterministic: every regime has its own recorded seed, and no timestamp is written, so rerunning the script reproduces each file byte for byte.
* -   In the JSON files, finite values are written using JavaScript's number-to-string conversion (the shortest decimal which round-trips). As JSON has no representation for them, `NaN`, `+infinity`, and `-infinity` are written as the strings `"NaN"`, `"Infinity"`, and `"-Infinity"`, and `-0` is written as `-0.0`, since `String( -0 )` drops the sign.
*/

/* eslint-disable n/no-sync */

'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var mkdirSync = require( 'fs' ).mkdirSync;
var exists = require( '@stdlib/fs/exists' ).sync;
var writeFileSync = require( '@stdlib/fs/write-file' ).sync;
var uniform = require( '@stdlib/random/base/uniform' ).factory;
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var isNegativeZero = require( '@stdlib/math/base/assert/is-negative-zero' );
var ln = require( '@stdlib/math/base/special/ln' );
var exp = require( '@stdlib/math/base/special/exp' );
var abs = require( '@stdlib/math/base/special/abs' );
var max = require( '@stdlib/math/base/special/max' );
var min = require( '@stdlib/math/base/special/min' );
var pow = require( '@stdlib/math/base/special/pow' );
var PINF = require( '@stdlib/constants/float64/pinf' );
var NINF = require( '@stdlib/constants/float64/ninf' );
var FLOAT64_MAX = require( '@stdlib/constants/float64/max' );
var SMALLEST_NORMAL = require( '@stdlib/constants/float64/smallest-normal' );
var SMALLEST_SUBNORMAL = require( '@stdlib/constants/float64/smallest-subnormal' );
var format = require( '@stdlib/string/format' );


// VARIABLES //

// Output directory:
var DIR = resolve( __dirname, '..', 'test', 'fixtures', 'inputs' );

// Number of variates per regime:
var N = 500;

// Base seed; regime `i` (in the order below) uses `SEED + i`:
var SEED = 20261031;

// A region is sampled log-uniformly (uniformly in the exponent) when its bounds have the same sign, neither is zero, and their magnitudes are more than this factor apart; otherwise, it is sampled uniformly:
var LOG_UNIFORM_RATIO = 10.0;

// The ten regimes of `log1p`'s existing Julia fixtures (`test/fixtures/julia/runner.jl`), with the same bounds:
var REGIMES = [
	[ 'tiny_negative', -pow( 2.0, -54 ), 0.0 ],
	[ 'tiny_positive', 0.0, pow( 2.0, -54 ) ],
	[ 'small_negative', -pow( 2.0, -29 ), -pow( 2.0, -54 ) ],
	[ 'small_positive', pow( 2.0, -54 ), pow( 2.0, -29 ) ],
	[ 'medium_negative', -0.41422, -0.2929 ],
	[ 'medium_positive', 0.2929, 0.41422 ],
	[ 'large_negative', -0.9999, -0.41422 ],
	[ 'large_positive', 0.41422, 100.0 ],
	[ 'big_positive', pow( 2.0, 30 ), pow( 2.0, 52 ) ],
	[ 'huge_positive', 1.0e200, 1.0e300 ]
];

// Edge cases, written in their own file:
var EDGE_CASES = [
	NINF,
	-FLOAT64_MAX,
	-2.0,
	-1.0 - pow( 2.0, -52 ), // largest double below -1
	-1.0,
	-1.0 + pow( 2.0, -53 ), // smallest double above -1
	-1.0 + pow( 2.0, -52 ),
	-1.0 + pow( 2.0, -51 ),
	-SMALLEST_NORMAL,
	-SMALLEST_SUBNORMAL * 2.0,
	-SMALLEST_SUBNORMAL,
	-0.0,
	0.0,
	SMALLEST_SUBNORMAL,
	SMALLEST_SUBNORMAL * 2.0,
	SMALLEST_NORMAL,
	FLOAT64_MAX,
	PINF,
	NaN
];


// FUNCTIONS //

/**
* Serializes a double as a JSON value.
*
* @private
* @param {number} x - input value
* @returns {string} JSON value
*/
function serialize( x ) {
	if ( isnan( x ) ) {
		return '"NaN"';
	}
	if ( x === PINF ) {
		return '"Infinity"';
	}
	if ( x === NINF ) {
		return '"-Infinity"';
	}
	if ( isNegativeZero( x ) ) {
		return '-0.0';
	}
	return String( x );
}

/**
* Generates pseudorandom variates within a region.
*
* @private
* @param {number} lo - lower bound
* @param {number} hi - upper bound
* @param {NonNegativeInteger} n - number of variates
* @param {PositiveInteger} seed - PRNG seed
* @returns {Object} variates and a description of how they were drawn
*/
function variates( lo, hi, n, seed ) {
	var dist;
	var sign;
	var rand;
	var out;
	var a;
	var b;
	var v;

	rand = uniform({
		'seed': seed
	});
	out = [];
	if (
		lo !== 0.0 &&
		hi !== 0.0 &&
		( lo < 0.0 ) === ( hi < 0.0 ) &&
		( max( abs( lo ), abs( hi ) ) / min( abs( lo ), abs( hi ) ) ) >
			LOG_UNIFORM_RATIO
	) {
		dist = 'log-uniform';
		sign = ( lo < 0.0 ) ? -1.0 : 1.0;
		a = ln( abs( lo ) );
		b = ln( abs( hi ) );
		if ( a > b ) {
			v = a;
			a = b;
			b = v;
		}
		while ( out.length < n ) {
			v = sign * exp( rand( a, b ) );

			// Reject the rare variate which rounding pushes outside the region:
			if ( v >= lo && v <= hi ) {
				out.push( v );
			}
		}
	} else {
		dist = 'uniform';
		while ( out.length < n ) {
			out.push( rand( lo, hi ) );
		}
	}
	return {
		'x': out,
		'distribution': dist,
		'prng': rand.PRNG.NAME
	};
}

/**
* Writes a shared input file.
*
* @private
* @param {string} name - regime name
* @param {NumberArray} x - input values
* @param {Object} meta - metadata
*/
function write( name, x, meta ) {
	var json;
	var i;

	json = [];
	for ( i = 0; i < x.length; i++ ) {
		json.push( serialize( x[ i ] ) );
	}
	json = format( '{"regime":"%s","x":[%s],"meta":%s}\n', name, json.join( ',' ), JSON.stringify( meta ) );
	writeFileSync( resolve( DIR, name+'.json' ), json );
}


// MAIN //

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var seed;
	var out;
	var r;
	var i;

	if ( !exists( DIR ) ) {
		mkdirSync( DIR );
	}
	for ( i = 0; i < REGIMES.length; i++ ) {
		r = REGIMES[ i ];
		seed = SEED + i;
		out = variates( r[ 1 ], r[ 2 ], N, seed );
		write( r[ 0 ], out.x, {
			'generator': 'scripts/inputs.js',
			'domain': [ r[ 1 ], r[ 2 ] ],
			'distribution': out.distribution,
			'prng': out.prng,
			'seed': seed,
			'n': out.x.length
		});
	}
	write( 'edge_cases', EDGE_CASES, {
		'generator': 'scripts/inputs.js',
		'domain': null,
		'distribution': 'hand-picked',
		'prng': null,
		'seed': null,
		'n': EDGE_CASES.length
	});
}

main();
